INSERT INTO `notifications` VALUES (1,'Cocktail de bienvenue ce soir à 18h au bar rooftop','Welcome cocktail tonight at 6pm at the rooftop bar','Begrüßungscocktail heute Abend um 18 Uhr an der Rooftop Bar','Cóctel de bienvenida esta noche a las 18:00 en el bar rooftop','Coquetel de boas-vindas às 18h no bar do terraço','كوكتيل ترحيبي الليلة في الساعة 6 مساءً في البار الموجود على السطح','今晚6点在屋顶酒吧享用迎宾鸡尾酒','今夜午後6時、屋上バーでウェルカムカクテル','Приветственный коктейль сегодня в 18:00 в баре на крыше',1,1,'2026-04-07 01:49:37',1),(2,'Navette aéroport disponible — Contactez la réception','Airport shuttle available — Contact reception','Flughafentransfer verfügbar — Kontaktaufnahme','Traslado aeropuerto disponible — recepción de contacto','Transporte de/para o aeroporto disponível — Contacte a receção','تتوفر خدمة نقل ذهابًا وإيابًا إلى المطار — مكتب الاستقبال','提供机场班车—联系前台','空港シャトルが利用可能—コンタクトレセプション','Трансфер от/до аэропорта — Стойка регистрации',1,2,'2026-04-07 01:49:37',1),(3,'Petit-déjeuner servi de 6h30 à 10h30','Breakfast served from 6:30am to 10.30am','Frühstück von 6:30 Uhr bis 10.30 Uhr','Desayuno servido de 6:30 a 10.30 horas','Pequeno-almoço servido das 6:30 às 10:30','الإفطار خدم من الساعة 6:30 صباحاً إلى الساعة 30/10 صباحاً','早餐供应时间为上午6:30至上午10:30','朝食は午前6時30分から午前10時30分まで','Завтрак подается с 6:30 до 10:30',1,3,'2026-04-07 01:49:37',1),(4,'Soirée rumba en live tous les jeudis à partir de 19h au bord de la piscine.','Live rumba evening every Thursday from 7pm by the pool.','Live Rumba Abend jeden Donnerstag ab 19 Uhr am Pool.','Noche de rumba en vivo todos los jueves a partir de las 19:00 h en la piscina.','Festa de rumba ao vivo todas as quintas-feiras a partir das 19h na piscina.','حفلة رومبا حية كل خميس من الساعة 7 مساءً بجوار المسبح.','每周四晚上7点至泳池边举办伦巴舞现场派对。','毎週木曜日の午後7時からプールサイドでのライブランバパーティー。','Вечеринка с румбой каждый четверг с 19:00 у бассейна.',1,0,'2026-04-07 16:20:14',1),(5,'Bienvenue à ConnectBé!','Welcome to ConnectBé!',NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,1,'2026-04-10 00:35:39',1),(6,'Attention Canicule !',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,0,'2026-05-01 20:17:52',2);
