INSERT INTO `service_translations` VALUES (1,1,'fr','Massage Africain','Massage relaxant aux huiles essentielles pour libérer les tensions musculaires profondément.','Libération des tensions;Amélioration circulation;Détente profonde'),(2,1,'en','African Massage','Relaxing massage with essential oils to release muscle tensions deeply.','Release of tensions;Improvement of traffic; Deep relaxation'),(3,2,'fr','Soin Visage','Soin hydratant et régénérant sur mesure, adapté à votre type de peau.','Hydratation intense;Éclat immédiat;Anti-âge'),(4,2,'en','Facial Care','Custom moisturizing and regenerating treatment adapted to your skin type.','Deep hydration;Instant glow;Anti-aging'),(5,3,'fr','Gommage Corps','Exfoliation douce pour éliminer les cellules mortes et révéler une peau soyeuse.','Peau veloutée;Éclat naturel;Préparation bronzage'),(6,3,'en','Body Scrub','Gentle exfoliation to eliminate dead cells and reveal silky skin.','Velvety skin;Natural glow;Tan preparation'),(7,4,'fr','Aromathérapie','Voyage sensoriel par les huiles essentielles biologiques pour une relaxation totale.','Stress réduit;Sommeil amélioré;Équilibre émotionnel'),(8,4,'en','Aromatherapy','Sensory journey through organic essential oils for total relaxation.','Reduced stress;Improved sleep;Emotional balance'),(9,5,'fr','Massage Pierres Chaudes','Les pierres volcaniques chaudes pénètrent les muscles pour un soin unique et profond.','Chaleur thérapeutique;Douleurs soulagées;Bien-être total'),(10,5,'en','Hot Stone Massage','Volcanic hot stones penetrate muscles for a unique and deep treatment.','Therapeutic heat;Pain relief;Total well-being'),(11,6,'fr','Massage Duo','Partagez un moment de bien-être unique côte à côte dans notre salle couples.','Moment partagé;Cabine privée;Huiles au choix'),(12,6,'en','Couple Massage','Share a unique wellness moment side by side in our couple suite.','Shared moment;Private suite;Choice of oils'),(13,1,'de','Afrikanische Massage','Entspannende Massage mit ätherischen Ölen, um Muskelspannungen tief zu lösen.','Freisetzung von Spannungen;Verbesserung des Verkehrs; Tiefe Entspannung'),(14,1,'es','Masaje africano','Masaje relajante con aceites esenciales para liberar las tensiones musculares profundamente.','Liberación de las tensiones; Mejoramiento del tráfico; Relajación profunda'),(15,1,'pt','Massagem Africana','Massagem relaxante com óleos essenciais para liberar profundamente a tensão muscular.','Liberação de Tensão;Melhoria da Circulação;Relaxamento Profundo'),(16,1,'ar','الكتلة الأفريقية','تدليك مريح بالزيوت العطرية لتخفيف توتر العضلات بعمق.','إطلاق التوترات؛ تعزيز حركة المرور؛ الاسترخاء العميق'),(17,1,'zh','非洲按摩','使用精油进行放松按摩，深度缓解肌肉紧张。','张力释放；循环改善；深度放松'),(18,1,'ja','アフリカのマッサージ','エッセンシャルオイルでリラックスマッサージし、筋肉の緊張を深く和らげます。','緊張の解放;交通の改善;深い弛緩'),(19,1,'ru','Африканский массаж','Расслабляющий массаж с эфирными маслами для глубокого снятия мышечного напряжения.','Снятие напряжения;улучшение кровообращения; глубокая релаксация'),(33,7,'fr','Massage relaxant','Pour un moment de détente','Détente; Santé'),(35,7,'en','Relaxing massage','For a moment of relaxation','Welfare; Health'),(36,7,'de','Entspannungsmassage','Nur für einen Moment entspannen …','Wohlfahrt; Gesundheit'),(37,7,'es','Masaje relajante','Por un momento de relajación','Bienestar; salud'),(38,7,'pt','Massagem relaxante','Para um momento de relaxamento','Bem-estar; Saúde'),(39,7,'ar','التدليك الاسترخاء','لأوقات الاسترخاء','الرعاية الصحية'),(40,7,'zh','放松的按摩','放松一会儿','福利;保健'),(41,7,'ja','リラックスマッサージ','リラックスの瞬間のために','福祉・保健'),(42,7,'ru','Расслабляющий массаж','На мгновение расслабления','Расслабление; Здоровье'),(79,8,'fr','Rituel Beurre de Karité','Soin corporel signature à base de beurre de karité pur, issu des coopératives féminines locales, pour une peau nourrie et un moment de détente ancré dans les traditions burkinabè.','Hydratation profonde ; Peau adoucie ; Soutien à l\'artisanat local'),(80,8,'en','Shea Butter Ritual','Signature body treatment with pure shea butter sourced from local women\'s cooperatives, nourishing the skin in a ritual rooted in Burkinabè tradition.','Deep hydration ; Softened skin ; Supports local craftsmanship'),(81,9,'fr','Petit-Déjeuner Sahélien','Buffet matinal mêlant classiques continentaux et spécialités locales : bouillie de mil, beignets, jus de bissap et de gingembre, fruits de saison.','Produits locaux ; Options végétariennes ; Fait maison'),(82,9,'en','Sahelian Breakfast','Morning buffet blending continental classics with local specialties: millet porridge, beignets, hibiscus and ginger juice, seasonal fruit.','Local produce ; Vegetarian options ; Homemade'),(83,10,'fr','Dîner Terrasse Fusion Afro-Internationale','Cuisine de saison entre saveurs burkinabè revisitées et influences internationales, servie sur la terrasse du restaurant.','Cadre en plein air ; Carte évolutive ; Chef local'),(84,10,'en','Afro-International Fusion Terrace Dinner','Seasonal cuisine pairing reinvented Burkinabè flavors with international influences, served on the restaurant terrace.','Open-air setting ; Rotating menu ; Local chef'),(85,11,'fr','Accès Piscine à Débordement','Profitez de la piscine à débordement de l\'hôtel, transats et service bar au bord de l\'eau.','Vue dégagée ; Service au bord de l\'eau ; Serviettes fournies'),(86,11,'en','Infinity Pool Day Access','Enjoy the hotel\'s infinity pool with sun loungers and poolside bar service.','Open views ; Poolside service ; Towels provided'),(87,12,'fr','Yoga au Lever du Soleil','Séance de yoga en plein air face au jardin, animée par un professeur local, pour démarrer la journée en pleine sérénité.','Cadre naturel ; Tous niveaux ; Professeur local'),(88,12,'en','Sunrise Yoga','Outdoor yoga session facing the garden, led by a local instructor, to start the day in full serenity.','Natural setting ; All levels ; Local instructor'),(89,13,'fr','Transfert Aéroport Ouagadougou (OUA)','Navette privée entre l\'aéroport international de Ouagadougou et l\'hôtel, chauffeur à votre accueil avec pancarte nominative.','Accueil personnalisé ; Suivi de vol ; Véhicule climatisé'),(90,13,'en','Ouagadougou Airport Transfer (OUA)','Private shuttle between Ouagadougou International Airport and the hotel, driver waiting with a name board.','Personal welcome ; Flight tracking ; Air-conditioned vehicle'),(91,14,'fr','Voiture avec Chauffeur Privé — Journée','Location de véhicule climatisé avec chauffeur pour vos déplacements en ville ou vos excursions à la journée.','Chauffeur francophone ; Flexibilité de l\'itinéraire ; Véhicule climatisé'),(92,14,'en','Private Car with Driver — Full Day','Air-conditioned vehicle with driver for city trips or full-day excursions.','French-speaking driver ; Flexible itinerary ; Air-conditioned vehicle'),(93,15,'fr','Soirée Concert Live — Rythmes d\'Afrique','Concert live hebdomadaire au bar de l\'hôtel avec des musiciens locaux : afrobeat, coupé-décalé et rythmes traditionnels revisités.','Musiciens locaux ; Ambiance conviviale ; Bar sur place'),(94,15,'en','Live Concert Night — Rhythms of Africa','Weekly live concert at the hotel bar featuring local musicians: afrobeat, coupé-décalé and reimagined traditional rhythms.','Local musicians ; Friendly atmosphere ; On-site bar'),(95,16,'fr','Cinéma Plein Air','Projection en plein air dans le jardin de l\'hôtel, films africains et internationaux, transats et pop-corn.','Jardin aménagé ; Sélection de films africains ; Pop-corn offert'),(96,16,'en','Open-Air Cinema','Open-air screening in the hotel garden, African and international films, loungers and popcorn.','Landscaped garden ; African film selection ; Free popcorn'),(97,17,'fr','Guide Touristique Personnel','Guide francophone/anglophone à disposition pour organiser vos visites de Ouagadougou et de ses environs sur-mesure.','Guide certifié ; Circuit sur-mesure ; Bilingue FR/EN'),(98,17,'en','Personal Tour Guide','French/English-speaking guide available to arrange tailor-made visits of Ouagadougou and its surroundings.','Certified guide ; Tailor-made itinerary ; Bilingual FR/EN'),(99,18,'fr','Blanchisserie Express','Service de blanchisserie et repassage avec retour sous 4 heures pour les demandes urgentes.','Retour rapide ; Repassage inclus ; Prix à la pièce'),(100,18,'en','Express Laundry','Laundry and pressing service with 4-hour turnaround for urgent requests.','Fast turnaround ; Pressing included ; Priced per item'),(101,19,'fr','Soirée Contes du Griot','Un griot traditionnel partage légendes, proverbes et histoires du Burkina Faso au son de la kora, dans le jardin de l\'hôtel.','Immersion culturelle ; Moment convivial en famille ; Découverte du patrimoine oral'),(102,19,'en','Griot Storytelling Evening','A traditional griot shares legends, proverbs and stories of Burkina Faso to the sound of the kora, in the hotel garden.','Cultural immersion ; Family-friendly moment ; Discover oral heritage'),(103,20,'fr','Atelier Teinture Bogolan','Initiez-vous à l\'art traditionnel du bogolan (tissu teint à la boue) avec un artisan local et repartez avec votre création.','Artisan local ; Création à emporter ; Technique traditionnelle'),(104,20,'en','Bogolan Dyeing Workshop','Learn the traditional art of bogolan (mud-dyed cloth) with a local craftsperson and take home your own creation.','Local artisan ; Take-home creation ; Traditional technique'),(105,21,'fr','Initiation au Djembé','Cours d\'initiation au djembé avec un percussionniste professionnel : rythmes traditionnels et jeu collectif.','Percussionniste professionnel ; Instruments fournis ; Ouvert aux débutants'),(106,21,'en','Djembe Drumming Introduction','Introductory djembe lesson with a professional percussionist: traditional rhythms and group play.','Professional percussionist ; Instruments provided ; Beginner friendly'),(107,22,'fr','Visite Guidée de Ouagadougou','Découverte du Grand Marché, de la Cathédrale, du Palais du Moro-Naba et du Village Artisanal avec un guide local francophone.','Transport inclus ; Guide local ; Sites emblématiques'),(108,22,'en','Guided Tour of Ouagadougou','Discover the Grand Marché, the Cathedral, the Moro-Naba Palace and the Village Artisanal with a local French-speaking guide.','Transport included ; Local guide ; Landmark sites'),(109,23,'fr','Excursion aux Caïmans Sacrés de Bazoulé','Demi-journée à Bazoulé pour observer de près les caïmans sacrés, dans le respect des traditions locales.','Site naturel unique ; Guide et transport inclus ; Expérience culturelle'),(110,23,'en','Sacred Crocodiles of Bazoulé Excursion','Half-day trip to Bazoulé to observe the sacred crocodiles up close, in keeping with local traditions.','Unique natural site ; Guide and transport included ; Cultural experience'),(111,24,'fr','Tournée des Marchés Artisanaux','Circuit shopping accompagné dans les marchés et coopératives d\'artisanat de Ouagadougou : bronze, tissage, bijoux.','Accompagnement personnalisé ; Coopératives locales ; Artisanat authentique'),(112,24,'en','Artisan Markets Tour','Guided shopping circuit through Ouagadougou\'s craft markets and cooperatives: bronze, weaving, jewelry.','Personal guide ; Local cooperatives ; Authentic craftsmanship'),(113,25,'fr','Atelier Cuisine — Tô & Sauce Gombo','Apprenez à préparer le tô et sa sauce gombo aux côtés du chef, puis dégustez votre création.','Chef local ; Recette traditionnelle ; Dégustation incluse'),(114,25,'en','Cooking Class — Tô & Okra Sauce','Learn to prepare tô and its okra sauce alongside the chef, then taste your own creation.','Local chef ; Traditional recipe ; Tasting included'),(115,26,'fr','Dégustation Dolo & Bissap','Découverte commentée des boissons traditionnelles burkinabè : dolo (bière de mil) et bissap (hibiscus), avec accompagnements locaux.','Dégustation commentée ; Produits locaux ; Option sans alcool'),(116,26,'en','Dolo & Bissap Tasting','Guided tasting of traditional Burkinabè beverages: dolo (millet beer) and bissap (hibiscus), with local accompaniments.','Guided tasting ; Local products ; Non-alcoholic option'),(117,27,'fr','Dîner sous les Étoiles','Table privée dans le jardin de l\'hôtel, menu dégustation de spécialités burkinabè revisitées, service aux chandelles.','Table privée ; Menu dégustation ; Service aux chandelles'),(118,27,'en','Dinner Under the Stars','Private table in the hotel garden, tasting menu of reinvented Burkinabè specialties, candlelit service.','Private table ; Tasting menu ; Candlelit service'),(119,8,'de','Ritualbutter der Karität','Reine Sheabutter Unterschrift Körperpflege, von lokalen Frauengenossenschaften, für eine gepflegte Haut und einen Moment der Entspannung in Burkinabe Traditionen verwurzelt.','Tiefe Feuchtigkeit; weiche Haut; Unterstützung für lokale Handwerke'),(120,8,'es','Ritual Butter of Karity','Pura manteca de manteca de manteca, de las cooperativas locales de mujeres, para una piel nutrida y un momento de relajación arraigado en las tradiciones de Burkina Faso.','Hidratación profunda; piel suave; Apoyo a la artesanía local'),(121,8,'pt','Manteiga Ritual da Caridade','Cuidados corporais puros de manteiga de karité, de cooperativas locais de mulheres, para uma pele nutrida e um momento de relaxamento enraizado nas tradições Burkinabe.','Hidratação profunda; Pele macia; Suporte para artesanato local'),(122,8,'ar','بوتر ريتال كاريتي','من تعاونيات النساء المحليات من أجل بشرة مغذية ولحظة من الاسترخاء المتأصل في تقاليد بوركينابي.','التهوية العميقة؛ الجلد الصالح؛ دعم الحرف المحلية'),(123,8,'zh','Karity的礼仪奶油','纯奶油标志身体护理,来自当地妇女合作社,以养活皮肤并让布基纳法索传统产生放松.','深水合; 软皮肤; 支持本地工艺'),(124,8,'ja','カルティの儀式バター','地元の女性の協同組合からの純粋なシアバターシグネチャーボディケア、養われた肌とブルキナベの伝統に根ざしたリラックスの瞬間.','深い水和;柔らかい皮;ローカル技術のためのサポート'),(125,8,'ru','Ритуал с маслом ши','Фирменный уход за телом на основе чистого масла ши от местных женских кооперативов для увлажненной кожи и момента расслабления, уходящего корнями в традиции Буркина-Фасо.','Глубокое увлажнение; смягченная кожа; поддержка местного мастерства'),(126,9,'de','Frühstück Sahelian','Morgenbuffet kombiniert kontinentale Klassiker und lokale Spezialitäten: Hirsekochen, Donuts, Bissap und Ingwersaft, saisonale Früchte.','Lokale Ausgänge; Vegetarische Optionen; Hausgemacht'),(127,9,'es','Desayuno saheliano','Buffet matutino que combina los clásicos continentales y las especialidades locales: hierva suave, donuts, bissap y jugo de jengibre, frutas estacionales.','Salidas locales; opciones vegetarianas; casero'),(128,9,'pt','Pequeno-almoço Sahelian','Bufê matutino combinando clássicos continentais e especialidades locais: milheto ferver, donuts, bissap e suco de gengibre, frutas sazonais.','Saídas locais; Opções vegetarianas; Caseiros'),(129,9,'ar','فطور الساحل','صبغة صباحية تجمع بين الكلاسيكيات القارية والتخصصات المحلية: الغليان، الدونات، البسكويت وعصير الزنجبيل، الفواكه الموسمية.','النواتج المحلية؛ والخيارات النباتية؛'),(130,9,'zh','萨赫勒早餐','早上自助餐结合了大陆经典和地方特产:小米煮沸,甜甜圈,双萨和生姜汁,季节性水果.','当地产出; 蔬菜选择; 自制'),(131,9,'ja','朝食 Sahelian','コンチネンタルな古典と地元の特産品を組み合わせたモーニングブッフェ:フライパン、ドーナツ、ビスサップ、ジンジャージュース、季節のフルーツ.','ローカル出力; ベジタリアンオプション; 自家製'),(132,9,'ru','Сахельский завтрак','Утренний шведский стол, смешивающий континентальную классику и местные деликатесы: пшенную кашу, пончики, биссап и имбирный сок, сезонные фрукты.','Местные продукты; Вегетарианские блюда; Домашние'),(133,10,'de','Abendessen Terrasse Fusion African-International','Saisonale Küche zwischen neu besuchten Burkinabe Aromen und internationalen Einflüssen, serviert auf der Restaurantterrasse.','Außenrahmen; Evolutionskarte; Local Chief'),(134,10,'es','Cena Terraza Fusión África-Internacional','Cocina estacional entre sabores revisitados de Burkina Faso e influencias internacionales, servida en la terraza del restaurante.','Marco exterior; Mapa evolutivo; Jefe Local'),(135,10,'pt','Jantar Terraço Fusão Africano-Internacional','Cozinha sazonal entre sabores Burkinabe revisitados e influências internacionais, servido no terraço do restaurante.','Quadro exterior; Mapa evolutivo; Chefe local'),(136,10,'ar','Dinner Terrace Fusion African-International','المكعب الموسمي بين نكهات (بوركينابي) المُعاد بحثها والتأثيرات الدولية، خدم على شرفة المطعم.','الإطار الخارجي؛ خريطة التطور؛ رئيس محلي'),(137,10,'zh','非洲国际','在重新审视的布基纳法索风味和国际影响之间的季节性烹饪,在餐厅露台上服务.','室外框架; 演化图; 本地主管'),(138,10,'ja','ディナーテラス フュージョン アフリカ インターナショナル','レストランテラスでは、バーキナベの風味と国際的影響を見直し、季節の料理を楽しめます.','屋外フレーム、進化地図、ローカルチーフ'),(139,10,'ru','Афро-интернациональная фьюжн-терраса','На террасе ресторана подают блюда сезонной кухни с обновленными вкусами буркинабской кухни и интернациональными влияниями.','Открытая обстановка; масштабируемая карта; местный шеф-повар'),(140,11,'de','Poolzugang in Overflow','Genießen Sie den Infinity-Pool des Hotels, Liegestühle und Barservice am Wasser.','Offene Aussicht; Waterfront Service; Handtücher vorhanden'),(141,11,'es','Acceso a la piscina en el Desbordamiento','Disfrute de la piscina infinita del hotel, sillas de cubierta y servicio de bar junto al agua.','Vista abierta; Servicio frente al agua; Toallas proporcionadas'),(142,11,'pt','Acesso de piscina em Overflow','Desfrute da piscina infinita do hotel, espreguiçadeiras e serviço de bar junto à água.','Vista aberta; Serviço Waterfront; Toalhas fornecidas'),(143,11,'ar','الدخول إلى البراميل','تمتعوا بحمام الفنادق و الكراسي وخدمة البار بالماء.','وجهة نظر مفتوحة؛ خدمات واجهة المياه؛ المناشف المقدمة'),(144,11,'zh','在重叠流中集合访问','在水边享受酒店、甲板椅和酒吧的无限服务.','开放视图; 水口服务; 提供的毛巾'),(145,11,'ja','Overflowのプールアクセス','ホテルの無限プール、デッキチェア、バーを水でお楽しみください.','オープンビュー、ウォーターフロントサービス、タオル提供'),(146,11,'ru','Доступ к панорамному бассейну','Наслаждайтесь панорамным бассейном отеля, шезлонгами и баром на набережной.','Ясный вид; услуги на набережной; полотенца предоставляются.'),(147,12,'de','Yoga im Sonnenaufgang','Outdoor Yoga-Session vor dem Garten, von einem lokalen Lehrer animiert, um den Tag in Gelassenheit zu beginnen.','Natürliche Einstellung; Alle Ebenen; lokale Professor'),(148,12,'es','Yoga en el amanecer','Sesión de yoga al aire libre frente al jardín, animada por un maestro local, para comenzar el día en la serenidad.','Natural setting; All levels; Local Professor'),(149,12,'pt','Yoga no nascer do sol','Sessão de yoga ao ar livre em frente ao jardim, animado por um professor local, para começar o dia em serenidade.','Conjunto natural; Todos os níveis; Professor Local'),(150,12,'ar','Yoga in the Sunrise','دورة اليوغا في الهواء الطلق أمام الحديقة، محاكاة من قبل معلم محلي، لبدء اليوم في الحيض.','الوضع الطبيعي؛ جميع المستويات؛ أستاذ محلي'),(151,12,'zh','日出时的瑜伽','园前外出瑜伽会,由当地一位老师作动画,以宁静起行.','自然环境;各级;当地教授'),(152,12,'ja','日の出のヨガ','庭の前で野外ヨガのセッション、地元の教師によってアニメーション化、静けさで一日を始める.','自然な設定;すべてのレベル;ローカル教授'),(153,12,'ru','Йога на рассвете','Сессия йоги на свежем воздухе перед садом под руководством местного учителя, чтобы начать день в полной безмятежности.','Природные условия; Все уровни; Местный учитель'),(154,13,'de','Ouagadougou Flughafen (OAU) Transfer','Privates Shuttle zwischen dem internationalen Flughafen Ouagadougou und dem Hotel, Fahrer bei Ihrer Begrüßung mit nominativem Zeichen.','Personalisierter Empfang; Flugverfolgung; Klimaanlage'),(155,13,'es','Traslado aeropuerto de Uagadugú (OUA)','Traslado privado entre el aeropuerto internacional de Uagadugú y el hotel, conductor en su bienvenida con señal nominal.','Recepción personalizada; seguimiento de vuelos; vehículo con aire acondicionado'),(156,13,'pt','Transporte do Aeroporto de Ouagadougou (OUA)','Transporte privado entre o Aeroporto Internacional de Ouagadougou e o hotel, motorista na sua recepção com sinal nominativo.','Recepção personalizada; Rastreamento de voo; Veículo com ar condicionado'),(157,13,'ar','مطار واغادوغو (OAU)','مكوك خاص بين مطار واغادوغو الدولي والفندق، سائق في ترحيبكم مع علامة رمزية.','الاستقبال الشخصي؛ تعقب الرحلات الجوية؛ المركبات المكيفة جوا'),(158,13,'zh','瓦加杜古机场(非统组织)','瓦加杜古国际机场和酒店之间的私人穿梭机 司机欢迎你 并带有名牌.','个性化接待;飞行跟踪;空调车'),(159,13,'ja','Ouagadougou空港(OAU)送迎','Ouagadougou International Airportとホテル間のプライベートシャトル、正式なサインで歓迎のドライバー.','パーソナライズされたレセプション; フライトトラッキング; エアコン付き車両'),(160,13,'ru','Трансфер и