00,NULL,NULL,'+22625001234','Réservation 48h à l\'avance, transport et guide inclus.','08:00-13:00','Mar, Jeu, Sam',8,2,1,'2026-09-19 22:04:24'),(24,1,8,'tournee-marches-artisanaux',180,20000,NULL,NULL,'+22625001234','Réservation la veille, transport inclus.','09:00-12:00','Lun-Ven',10,3,1,'2026-09-19 22:04:24'),(25,1,9,'atelier-cuisine-to-sauce-gombo',90,18000,NULL,NULL,'+22625000301','Réservation la veille, groupes de 8 personnes maximum.','16:00-17:30','Mar, Jeu',8,1,1,'2026-09-19 22:04:24'),(26,1,9,'degustation-dolo-bissap',45,8000,NULL,NULL,'+22625000301','Réservation à la réception, version non-alcoolisée disponible.','18:00-19:00','Ven-Sam',10,2,1,'2026-09-19 22:04:24'),(27,1,9,'diner-sous-les-etoiles',120,35000,NULL,NULL,'+22625000301','Réservation 24h à l\'avance, idéal pour les occasions spéciales.','19:30-21:30','Lun-Dim',6,3,1,'2026-09-19 22:04:24');
