INSERT INTO `useful_contact_translations` VALUES (1,1,'fr','Dr Ouedraogo','Bon medecin',NULL),(2,1,'en','Dr. Ouedraogo','Good doctor',NULL),(3,1,'de','Dr. Ouedraogo','Guter Arzt',NULL),(4,1,'es','Dr. Ouedraogo','Buen médico',NULL),(5,1,'pt','Dr. Ouedraogo','Bom doutor',NULL),(6,1,'ar','Dr. Ouedraogo','طبيب جيد',NULL),(7,1,'zh','韦德拉奥戈博士','好医生',NULL),(8,1,'ja','オウドラゴ博士','良い医者',NULL),(9,1,'ru','Д-р Уэдраого','Хороший врач',NULL),(28,2,'fr','Police Secours','Numéro d\'urgence national de la Police Nationale, disponible 24h/24 pour tout danger immédiat.','Ouagadougou'),(29,2,'en','Police Emergency','National emergency number of the Burkina Faso Police, available 24/7 for any immediate danger.','Ouagadougou'),(30,3,'fr','Gendarmerie Nationale','Numéro d\'urgence de la Gendarmerie nationale du Burkina Faso, disponible 24h/24.','Ouagadougou'),(31,3,'en','National Gendarmerie','Emergency number of the Burkina Faso National Gendarmerie, available 24/7.','Ouagadougou'),(32,4,'fr','Sapeurs-Pompiers','Numéro d\'urgence national des sapeurs-pompiers : incendie, accident, secours à personne. Disponible 24h/24.','Ouagadougou'),(33,4,'en','Fire Brigade','National fire brigade emergency number: fire, accident, rescue. Available 24/7.','Ouagadougou'),(34,5,'fr','SAMU Ouagadougou','Service d\'Aide Médicale Urgente : appel gratuit pour toute urgence médicale nécessitant l\'envoi d\'une équipe médicalisée. Disponible 24h/24.','Ouagadougou'),(35,5,'en','SAMU Ouagadougou (Emergency Medical Service)','Toll-free emergency medical service dispatching a doctor and equipped ambulance. Available 24/7.','Ouagadougou'),(40,8,'fr','CHU Yalgado Ouédraogo','Principal centre hospitalier universitaire public de Ouagadougou, service d\'urgences ouvert 24h/24.','03 BP 7022, Ouagadougou 03'),(41,8,'en','Yalgado Ouédraogo University Hospital','Main public university hospital in Ouagadougou, with a 24/7 emergency department.','03 BP 7022, Ouagadougou 03'),(42,9,'fr','Clinique El Fateh-Suka','Clinique privée de spécialités médico-chirurgicales : médecine générale, gynéco-obstétrique, chirurgie, radiologie, laboratoire.','04 BP 8297, Ouagadougou 04'),(43,9,'en','El Fateh-Suka Clinic','Private medical-surgical clinic: general medicine, obstetrics-gynecology, surgery, radiology, laboratory.','04 BP 8297, Ouagadougou 04'),(44,10,'fr','Pharmacies de garde — Ouagadougou','Les pharmacies de la ville sont réparties en groupes qui assurent la garde à tour de rôle (nuits, dimanches, jours fériés). Consultez la liste actualisée sur le site de l\'Ordre National des Pharmaciens du Burkina Faso, ou demandez à la réception.','Ouagadougou'),(45,10,'en','On-Duty Pharmacies — Ouagadougou','City pharmacies are divided into rotating groups covering nights, Sundays and public holidays. Check the current schedule on the Burkina Faso National Order of Pharmacists website, or ask at reception.','Ouagadougou'),(48,12,'fr','Allo Taxi','Réservation de taxi par téléphone, jour et nuit, pour vos déplacements en ville.','Ouagadougou'),(49,12,'en','Allo Taxi','Phone taxi booking, day and night, for getting around the city.','Ouagadougou'),(50,13,'fr','SOTRACO — Bus urbain','Réseau de bus public de Ouagadougou, plusieurs lignes couvrant la ville. Service de 7h30 à 18h00.','2257 Avenue du Sanmatenga, Secteur 19, Ouagadougou'),(51,13,'en','SOTRACO — City Bus','Ouagadougou\'s public bus network, several lines covering the city. Runs 7:30 AM to 6:00 PM.','2257 Avenue du Sanmatenga, Secteur 19, Ouagadougou'),(52,14,'fr','Consulat Général du Niger','Représentation diplomatique du Niger au Burkina Faso — visas et assistance consulaire. Ouvert du lundi au vendredi sur rendez-vous. Email : saasayadi@gmail.fr','Arrondissement 12, Secteur 54, Avenue Charles Bila Kaboré, 11 BP 1015 CMS Ouaga 11, Ouagadougou'),(53,14,'en','Consulate General of Niger','Niger\'s diplomatic representation in Burkina Faso — visas and consular assistance. Open Monday to Friday by appointment. Email: saasayadi@gmail.fr','Arrondissement 12, Secteur 54, Avenue Charles Bila Kaboré, 11 BP 1015 CMS Ouaga 11, Ouagadougou'),(54,15,'fr','Ambassade du Mali','Standard de l\'ambassade — visas et assistance consulaire pour les ressortissants maliens. Ouvert lundi-jeudi 8h30-15h30, vendredi 8h30-12h30 et 14h-16h.','Avenue Pascal Zagré, Ouaga 2000, 01 BP 1911, Ouagadougou'),(55,15,'en','Embassy of Mali','Embassy switchboard — visas and consular assistance for Malian nationals. Open Monday-Thursday 8:30 AM-3:30 PM, Friday 8:30 AM-12:30 PM and 2-4 PM.','Avenue Pascal Zagré, Ouaga 2000, 01 BP 1911, Ouagadougou'),(56,16,'fr','Ambassade du Ghana','Standard de l\'ambassade — visas et assistance consulaire pour les ressortissants ghanéens. Ouvert du lundi au vendredi, 9h-14h.','Avenue du Capitaine Thomas Sankara, Paspanga, Ouagadougou'),(57,16,'en','Embassy of Ghana','Embassy switchboard — visas and consular assistance for Ghanaian nationals. Open Monday to Friday, 9:00 AM-2:00 PM.','Avenue du Capitaine Thomas Sankara, Paspanga, Ouagadougou'),(60,18,'fr','Banque Postale du Burkina Faso','Siège de la Banque Postale du Burkina Faso (BPBF) : ouverture de compte, retrait, change. Une seconde agence existe à Ouaga 2000, boulevard de l\'Insurrection populaire.','Avenue du Président Sangoulé Lamizana, Arrondissement 01, Secteur 03, 01 BP 1366, Ouagadougou'),(61,18,'en','Postal Bank of Burkina Faso','Head office of the Postal Bank of Burkina Faso (BPBF): account opening, cash withdrawal, currency exchange. A second branch is located in Ouaga 2000, Boulevard de l\'Insurrection Populaire.','Avenue du Président Sangoulé Lamizana, Arrondissement 01, Secteur 03, 01 BP 1366, Ouagadougou');
