INSERT INTO `wellness_service_translations` VALUES (1,1,'fr','Massage Suédois','Massage relaxant aux huiles essentielles pour libérer les tensions musculaires profondément.','Libération des tensions;Amélioration circulation;Détente profonde'),(2,1,'en','Swedish Massage','Relaxing massage with essential oils to release muscle tension deeply.','Tension relief;Improved circulation;Deep relaxation'),(3,2,'fr','Soin Visage','Soin hydratant et régénérant sur mesure, adapté à votre type de peau.','Hydratation intense;Éclat immédiat;Anti-âge'),(4,2,'en','Facial Care','Custom moisturizing and regenerating treatment adapted to your skin type.','Deep hydration;Instant glow;Anti-aging'),(5,3,'fr','Gommage Corps','Exfoliation douce pour éliminer les cellules mortes et révéler une peau soyeuse.','Peau veloutée;Éclat naturel;Préparation bronzage'),(6,3,'en','Body Scrub','Gentle exfoliation to eliminate dead cells and reveal silky skin.','Velvety skin;Natural glow;Tan preparation'),(7,4,'fr','Aromathérapie','Voyage sensoriel par les huiles essentielles biologiques pour une relaxation totale.','Stress réduit;Sommeil amélioré;Équilibre émotionnel'),(8,4,'en','Aromatherapy','Sensory journey through organic essential oils for total relaxation.','Reduced stress;Improved sleep;Emotional balance'),(9,5,'fr','Massage Pierres Chaudes','Les pierres volcaniques chaudes pénètrent les muscles pour un soin unique et profond.','Chaleur thérapeutique;Douleurs soulagées;Bien-être total'),(10,5,'en','Hot Stone Massage','Volcanic hot stones penetrate muscles for a unique and deep treatment.','Therapeutic heat;Pain relief;Total well-being'),(11,6,'fr','Massage Duo','Partagez un moment de bien-être unique côte à côte dans notre salle couples.','Moment partagé;Cabine privée;Huiles au choix'),(12,6,'en','Couple Massage','Share a unique wellness moment side by side in our couple suite.','Shared moment;Private suite;Choice of oils'),(17,1,'de','Schwedische Massage','Entspannende Massage mit ätherischen Ölen, um Muskelverspannungen tief zu lösen.',NULL),(18,1,'es','Masaje sueco','Masaje relajante con aceites esenciales para liberar las tensiones musculares profundamente.',NULL),(19,1,'pt','Massagem Sueca',NULL,NULL),(20,1,'ar','التجمع السويدي',NULL,NULL),(21,1,'zh','瑞典式按摩',NULL,NULL),(22,1,'ja','スウェーデン式マッサージ',NULL,NULL),(23,1,'ru','Шведский массаж',NULL,NULL);
